create extension if not exists pgcrypto;
create table if not exists profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,created_at timestamptz not null default now());
create table if not exists decisions(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,title text not null,question text not null,objective text,decision_type text not null default 'business',status text not null default 'draft',recommendation text,confidence numeric check(confidence between 0 and 100),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists research_runs(id uuid primary key default gen_random_uuid(),decision_id uuid not null references decisions(id) on delete cascade,status text not null default 'queued',query_count integer not null default 0,source_count integer not null default 0,started_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now());
create table if not exists sources(id uuid primary key default gen_random_uuid(),research_run_id uuid not null references research_runs(id) on delete cascade,url text not null,title text,publisher text,source_type text,published_at timestamptz,retrieved_at timestamptz not null default now(),authority_score numeric,relevance_score numeric,content_hash text);
create table if not exists evidence(id uuid primary key default gen_random_uuid(),decision_id uuid not null references decisions(id) on delete cascade,source_id uuid references sources(id) on delete set null,claim text not null,evidence_type text not null check(evidence_type in ('FACT','INFERENCE','ASSUMPTION','OPINION','UNKNOWN')),support_level text,confidence numeric check(confidence between 0 and 100),created_at timestamptz not null default now());
create table if not exists decision_factors(id uuid primary key default gen_random_uuid(),decision_id uuid not null references decisions(id) on delete cascade,name text not null,score numeric check(score between 0 and 100),rationale text);
create table if not exists recommendations(id uuid primary key default gen_random_uuid(),decision_id uuid not null references decisions(id) on delete cascade,recommendation text not null,confidence numeric check(confidence between 0 and 100),rationale text,created_at timestamptz not null default now());
create table if not exists decision_events(id uuid primary key default gen_random_uuid(),decision_id uuid not null references decisions(id) on delete cascade,event_type text not null,payload jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
alter table profiles enable row level security; alter table decisions enable row level security; alter table research_runs enable row level security; alter table sources enable row level security; alter table evidence enable row level security; alter table decision_factors enable row level security; alter table recommendations enable row level security; alter table decision_events enable row level security;
create policy "profiles own" on profiles for all using(auth.uid()=id) with check(auth.uid()=id);
create policy "decisions own" on decisions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
